"""Live control record for the RoboTwin limited-mode place_fan episode.

Run once against the episode service. Commands arrive as JSON lines on stdin:
  {"op":"observe"}
  {"op":"wait","seconds":2}
  {"op":"ee_pose","actions":[...],"note":"..."}
  {"op":"joint_position","actions":[...],"dt":0.05,"note":"..."}

Each request, response metadata, image, and proprioception snapshot is retained
under /app/output/episode for the trajectory record.
"""
from __future__ import annotations

import json
import pathlib
import sys
import time

import numpy as np
from PIL import Image
from rcb_client import Robot


OUT = pathlib.Path("/app/output/episode")
OUT.mkdir(parents=True, exist_ok=True)
EVENTS = OUT / "events.jsonl"


def write_obs(tag, obs):
    last_dir = OUT / "last"
    last_dir.mkdir(parents=True, exist_ok=True)
    for cam, arr in obs.last.items():
        Image.fromarray(np.ascontiguousarray(arr)).save(last_dir / f"{tag}_{cam}.jpg", quality=92)
    if obs.proprio is not None:
        np.save(OUT / f"{tag}_proprio.npy", obs.proprio)
    return {
        "meta": obs.meta,
        "proprio": obs.meta.get("proprio"),
        "cameras": obs.meta.get("cameras"),
        "last_cameras": sorted(obs.last),
    }


def record(obj):
    with EVENTS.open("a") as f:
        f.write(json.dumps(obj, default=lambda x: x.tolist() if hasattr(x, "tolist") else str(x)) + "\n")


def main():
    robot = Robot()
    spec = robot.spec()
    (OUT / "spec.json").write_text(json.dumps(spec, indent=2))
    print(json.dumps({"connected": robot.base, "spec": spec}, default=str), flush=True)
    obs = robot.get_obs(video="none")
    snapshot = write_obs("initial", obs)
    print(json.dumps({"initial": snapshot}, default=str), flush=True)
    record({"event": "initial_observation", "time": time.time(), "snapshot": snapshot})

    index = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
            op = req.get("op")
            note = req.get("note", "")
            if op == "observe":
                obs = robot.get_obs(video="none", include_depth=bool(req.get("depth", False)))
                snapshot = write_obs(f"obs_{index:03d}", obs)
                response = {"observation": snapshot}
            elif op == "wait":
                obs = robot.get_obs(seconds=float(req.get("seconds", 1)), video="none")
                snapshot = write_obs(f"wait_{index:03d}", obs)
                response = {"observation": snapshot}
            elif op in ("ee_pose", "joint_position"):
                actions = np.asarray(req["actions"], dtype=np.float32)
                kwargs = {"video": req.get("video", "none"), "note": note}
                if op == "joint_position":
                    kwargs["dt"] = float(req.get("dt", 0.05))
                res = robot.submit(op, actions, **kwargs)
                response = {"meta": res.meta, "last_cameras": sorted(res.last), "proprio": res.proprio}
                if res.last:
                    write_obs(f"action_{index:03d}", res)
                record({"event": "action", "time": time.time(), "op": op, "note": note,
                        "actions": actions, "meta": res.meta, "proprio": res.proprio})
            elif op == "status":
                response = {"status": robot.status()}
            elif op == "quit":
                print(json.dumps({"ok": True, "quit": True}), flush=True)
                break
            else:
                raise ValueError(f"unknown op {op!r}")
            index += 1
            print(json.dumps(response, default=lambda x: x.tolist() if hasattr(x, "tolist") else str(x)), flush=True)
        except Exception as exc:
            print(json.dumps({"error": type(exc).__name__, "detail": str(exc)}), flush=True)
            if type(exc).__name__ == "EpisodeOver":
                break


if __name__ == "__main__":
    main()
